//! Weight functions for pallet-work-verify. `()` holds the estimates used until the runtime ships
//! benchmarked weights (runtime/src/weights/, generated by scripts/run-benchmarks.sh).
#![allow(unused_parens, unused_imports)]

use polkadot_sdk::frame_support::weights::{constants::RocksDbWeight, Weight};

pub trait WeightInfo {
    fn bond() -> Weight;
    fn unbond() -> Weight;
    fn withdraw_unbonded() -> Weight;
    fn register_pool() -> Weight;
    fn set_pool_fee() -> Weight;
    fn distribute(p: u32) -> Weight;
    fn report_failed_check(r: u32) -> Weight;
}

impl WeightInfo for () {
    fn bond() -> Weight {
        RocksDbWeight::get().reads_writes(1, 1)
    }
    fn unbond() -> Weight {
        RocksDbWeight::get().reads_writes(2, 2)
    }
    fn withdraw_unbonded() -> Weight {
        RocksDbWeight::get().reads_writes(1, 1)
    }
    fn register_pool() -> Weight {
        RocksDbWeight::get().reads_writes(3, 1)
    }
    fn set_pool_fee() -> Weight {
        RocksDbWeight::get().reads_writes(1, 1)
    }
    fn distribute(p: u32) -> Weight {
        RocksDbWeight::get().reads_writes(2 + p as u64, 2 + p as u64)
    }
    fn report_failed_check(r: u32) -> Weight {
        RocksDbWeight::get()
            .reads_writes(6, 6)
            .saturating_add(Weight::from_parts(10_000 * r as u64, 0))
    }
}
